.orders-page{gap:1.35cqw}
.orders-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1.35cqw;flex-shrink:0}
.lillian-dashboard [data-slot=card].glass.orders-metric{gap:0;min-width:0;padding:0 0 min(1.3cqw,2.08dvh);border-radius:2cqw;transition:transform 320ms ease,box-shadow 320ms ease}
.orders-metric>strong{font-size:clamp(22px,2.2cqw,38px);font-weight:600;line-height:1.2;letter-spacing:-.045em;color:#303732;margin:.4cqw var(--widget-header-inset) .35cqw;font-variant-numeric:tabular-nums}
.orders-metric>span{margin:0 var(--widget-header-inset);font-size:clamp(9px,.65cqw,12px);color:#8e9d92}
.lillian-dashboard [data-slot=card].glass.orders-list-widget{flex:1;min-height:0;gap:0;padding:0;border-radius:2cqw;overflow:hidden}
.orders-result-count{font-size:clamp(9px,.65cqw,12px);color:#94a398}
.orders-controls{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:.5cqw var(--widget-header-inset) 1cqw;flex-shrink:0}
.orders-controls .page-filter-tabs{margin:0;gap:6px}
.orders-controls .page-filter-tabs button{height:30px;font-size:10px;padding:0 13px;transition:color 200ms,background 200ms}
.lillian-dashboard .orders-controls .page-filter-tabs button[aria-pressed=true]{background:#e8f2e4;color:#57874d}
.orders-search{display:flex;align-items:center;gap:8px;width:25%;min-width:140px;height:34px;border-radius:30px;padding:0 10px;color:#9aa79e}
.orders-search>svg{width:14px;height:14px;flex-shrink:0}
.lillian-dashboard .orders-search input{min-width:0;width:100%;height:100%;padding:0;border:0;box-shadow:none;background:transparent;font-size:10px;color:inherit;outline:none;border-radius:0}
.orders-search button{flex-shrink:0;color:inherit}
.orders-table-scroll{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;margin:0 var(--widget-header-inset);scrollbar-width:thin;outline-offset:-2px}
.orders-data-table{border-collapse:separate;border-spacing:0;width:100%;text-align:left;font-size:clamp(10px,.75cqw,13px);color:#7e8e83;white-space:nowrap}
.orders-data-table th{position:sticky;top:0;z-index:1;background:#f5f8f6;border-bottom:1px solid var(--dashboard-divider);padding:0 12px;font-weight:500;font-size:10px}
.orders-data-table th:first-child,.orders-data-table td:first-child{padding-left:0}
.orders-data-table th:last-child,.orders-data-table td:last-child{text-align:right;padding-right:0}
.orders-data-table th button{height:36px;padding:0;gap:7px;font-size:inherit;font-weight:500;color:#94a298;background:transparent}
.orders-data-table th:last-child button{margin-left:auto}
.orders-data-table th button svg{width:11px;height:11px;opacity:.6}
.orders-data-table th[aria-sort=ascending] button,.orders-data-table th[aria-sort=descending] button{color:#548554}
.orders-data-table td{padding:clamp(10px,1.2dvh,15px) 12px;border-bottom:1px solid var(--dashboard-divider);transition:background 180ms}
.orders-data-table tbody tr:last-child td{border-bottom:0}
.orders-data-table tbody tr:hover td{background:#c5ddc315}
.orders-id{color:#4a5f50;font-weight:500}
.orders-customer{display:block;color:#526a59;font-weight:500}
.orders-email,.orders-refund{display:block;font-size:9px;color:#a0ada4;margin-top:3px;font-weight:400}
.orders-value{font-variant-numeric:tabular-nums;color:#455e4d;font-weight:600}
.orders-status{display:inline-flex;align-items:center;gap:6px;border-radius:25px;padding:4px 10px;font-size:9px;color:#6b9068}
.orders-status i{height:5px;width:5px;border-radius:50%;background:#79ac62}
.orders-status.refunded{color:#a19462}.orders-status.refunded i{background:#b8b64b}
.orders-data-table .orders-empty{text-align:center;padding:40px 12px;color:#9aaa9e}
.orders-table-footer{display:flex;align-items:center;gap:20px;margin:0 var(--widget-header-inset);padding:12px 0;border-top:1px solid var(--dashboard-divider);flex-shrink:0;color:#91a095;font-size:10px}
.orders-table-footer>span{margin-right:auto}
.orders-table-footer label{display:flex;align-items:center;gap:8px}
.orders-table-footer select{font-size:10px;padding:3px 8px;border-radius:20px;cursor:pointer}
.orders-pagination{display:flex;align-items:center;gap:10px;font-variant-numeric:tabular-nums}
.orders-pagination button{border-radius:50%;color:#90a194;width:28px;height:28px}
.orders-pagination button svg{width:15px;height:15px}
.orders-demo-note{margin:-.6cqw 0 0;padding:0 2px;font-size:9px;color:#93a498;flex-shrink:0}
.lillian-dashboard[data-theme=dark] .orders-metric>strong{color:#d9e8dc}
.lillian-dashboard[data-theme=dark] .orders-data-table th{background:#2b4131}
.lillian-dashboard[data-theme=dark] :is(.orders-id,.orders-customer,.orders-value){color:#c1d6c6}
.lillian-dashboard[data-theme=dark] .orders-status{background:#314c37;border:1px solid var(--dashboard-border);color:#b3cfae}
.lillian-dashboard[data-theme=dark] .orders-controls .page-filter-tabs button[aria-pressed=true]{background:#3a513c;color:#c1d8bf}
@media(hover:hover) and (prefers-reduced-motion:no-preference){.orders-metric:hover{transform:scale(1.02)}}
@media(max-width:760px){
  .orders-page{gap:10px}
  .orders-metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  .lillian-dashboard [data-slot=card].glass.orders-metric{border-radius:18px;padding-bottom:10px}
  .orders-metric>strong{font-size:clamp(19px,3.2dvh,27px);margin:0 var(--widget-header-inset) 3px}
  .orders-metric>span{font-size:8px}
  .lillian-dashboard [data-slot=card].glass.orders-list-widget{border-radius:18px}
  .orders-controls{gap:8px;flex-wrap:wrap;padding:7px var(--widget-header-inset) 10px}
  .orders-controls .page-filter-tabs{gap:4px}
  .orders-controls .page-filter-tabs button{height:26px;padding:0 9px;font-size:9px}
  .orders-search{flex:1;width:auto;min-width:100px;height:28px;padding:0 8px;gap:5px}
  .orders-search>svg{width:12px;height:12px}
  .lillian-dashboard .orders-search input{font-size:9px}
  .orders-data-table{font-size:10px;min-width:580px}
  .orders-data-table td{padding:10px}
  .orders-table-footer{gap:8px;padding:8px 0;font-size:8px}
  .orders-table-footer label{gap:4px}
  .orders-table-footer select{font-size:9px;padding:2px 4px}
  .orders-pagination{gap:6px}
  .orders-pagination button{width:24px;height:24px}
  .orders-demo-note{font-size:7px;line-height:1.4;margin:0}
}
@media(max-height:500px) and (min-width:761px){.orders-metric>strong{font-size:22px}.orders-metric>span{font-size:8px}.orders-controls{padding-top:2px;padding-bottom:5px}.orders-controls .page-filter-tabs button{height:24px}.orders-search{height:26px}.orders-table-footer{padding:5px 0}.orders-demo-note{font-size:7px}}

import { reportingToday } from './reporting-period'

export type Order = {
  id: number
  customer: string
  email: string
  plan: 'Annual' | 'Monthly'
  createdAt: number
  status: 'Paid' | 'Refunded'
  value: number
  refund: number
  cost: number
}
export type OrderSort = 'id' | 'customer' | 'plan' | 'createdAt' | 'status' | 'value'
export type OrderStatus = 'All' | Order['status']

// Local demo amounts are stored in cents, including the cost used for profit.
export function createDemoOrders(today = reportingToday()): Order[] {
  const customers = ['Olivia Martin', 'Jackson Lee', 'Sofia Davis', 'Noah Williams', 'Emma Wilson', 'Liam Brown', 'Amelia Garcia', 'Lucas Miller', 'Mia Anderson', 'Ethan Thomas', 'Isabella Moore', 'Oliver Taylor', 'Ava Jackson', 'James White', 'Charlotte Harris', 'Henry Clark', 'Harper Lewis', 'Leo Robinson', 'Evelyn Walker', 'Jack Hall', 'Abigail Allen', 'Daniel Young', 'Ella King', 'William Wright']
  const values = [...Array<number>(6).fill(2300), ...Array<number>(4).fill(1900), ...Array<number>(7).fill(1200), ...Array<number>(7).fill(600)]
  return customers.map((customer, index) => ({
    id: 345 - index,
    customer,
    email: `${customer.toLowerCase().replace(' ', '.')}@example.com`,
    plan: index < 10 ? 'Annual' : 'Monthly',
    createdAt: new Date(today.getFullYear(), today.getMonth(), today.getDate(), 19, 30 - index * 30).getTime(),
    status: index > 21 ? 'Refunded' : 'Paid',
    value: values[index],
    refund: index > 21 ? values[index] : 0,
    cost: values[index] / 4,
  }))
}

export function filterOrders(orders: Order[], query: string, status: OrderStatus) {
  const term = query.trim().toLowerCase()
  return orders.filter(order => (status === 'All' || order.status === status) &&
    `${order.id} ${order.customer} ${order.email} ${order.plan} ${order.status} ${(order.value / 100).toFixed(2)}`.toLowerCase().includes(term))
}

export function sortOrders(orders: Order[], key: OrderSort, direction: 'asc' | 'desc') {
  return [...orders].sort((a, b) => {
    const left = a[key]
    const right = b[key]
    const result = typeof left === 'number' && typeof right === 'number' ? left - right : String(left).localeCompare(String(right))
    return (result || a.id - b.id) * (direction === 'asc' ? 1 : -1)
  })
}

export function orderTotals(orders: Order[]) {
  return orders.reduce((totals, order) => ({
    count: totals.count + 1,
    value: totals.value + order.value,
    refunds: totals.refunds + order.refund,
    profit: totals.profit + order.value - order.refund - order.cost,
  }), { count: 0, value: 0, refunds: 0, profit: 0 })
}

export const orderCurrency = (cents: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100)

'use client'

import { useId, useState } from 'react'
import { ArrowUpRight } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { ChartGrid } from './chart-grid'
import { chartCounts, chartTimes, parseChartPoints } from './chart-data'
import type { DetailData, DetailView } from './widget-details'
import './analytics-charts.css'

const palette = ['#4eb43c', '#369fb9', '#b8b64b']
const funnelPalette = ['#b8b64b', '#8abb57', '#4eb43c', '#32b691', '#369fb9']
const timePoints = '0,72 50,58 100,64 150,39 200,47 250,22 300,30 350,10 400,18'
const number = (value: string) => Number(value.replace(/[^0-9.]/g, '')) || 0
function arc(start: number, end: number) {
  const point = (angle: number) => ({ x: 100 + 88 * Math.cos(angle), y: 100 + 88 * Math.sin(angle) })
  const a = point(start), b = point(end)
  return `M100,100 L${a.x},${a.y} A88,88 0 ${end - start > Math.PI ? 1 : 0} 1 ${b.x},${b.y} Z`
}
function ChartHeading({ title, target, onDetails }: { title: string; target: DetailView; onDetails: (view: DetailView) => void }) {
  return <div className="card-heading"><h2>{title}</h2><Button className="round-button widget-details-button" aria-label={`View ${title.toLowerCase()} details`} onClick={() => onDetails(target)}><ArrowUpRight /></Button></div>
}
export function AnalyticsCharts({ data, onDetails }: { data: Record<DetailView, DetailData>; onDetails: (view: DetailView) => void }) {
  const [deviceHover, setDeviceHover] = useState<number | null>(null)
  const [timeHover, setTimeHover] = useState<number | null>(null)
  const fillId = useId()
  const devices = data.Visits.rows.map(row => ({ label: row[0], value: number(row[1]) }))
  const total = devices.reduce((sum, device) => sum + device.value, 0)
  const values = chartCounts(timePoints, 100, total)
  const timePoint = timeHover === null ? null : parseChartPoints(timePoints)[timeHover]
  let angle = -Math.PI / 2

  return <div className="analytics-charts-grid">
    <Card className="glass analytics-chart analytics-pie-card"><ChartHeading title="Visits by device" target="Visits" onDetails={onDetails} />
      <div className="analytics-pie-plot"><svg viewBox="0 0 200 200" role="img" aria-label={`Visits by device: ${devices.map(device => `${device.label} ${device.value}`).join(', ')}`}>
        {devices.map((device, index) => {
          const start = angle
          angle += device.value / (total || 1) * Math.PI * 2
          return <path key={device.label} d={arc(start, angle)} fill={palette[index % palette.length]} opacity={deviceHover === null || deviceHover === index ? .85 : .18} tabIndex={0} onPointerEnter={() => setDeviceHover(index)} onPointerLeave={() => setDeviceHover(null)} onFocus={() => setDeviceHover(index)} onBlur={() => setDeviceHover(null)}><title>{`${device.label}: ${device.value} visits (${Math.round(device.value / (total || 1) * 100)}%)`}</title></path>
        })}
      </svg>{deviceHover !== null && devices[deviceHover] && <div className="chart-hover-tooltip analytics-pie-tooltip" role="status"><span>{devices[deviceHover].label}</span><strong>{devices[deviceHover].value} visits · {Math.round(devices[deviceHover].value / (total || 1) * 100)}%</strong></div>}
      </div>
      <div className="analytics-pie-legend">{devices.map((device, index) => <Button variant="ghost" className="white-layer" key={device.label} onPointerEnter={() => setDeviceHover(index)} onPointerLeave={() => setDeviceHover(null)} onFocus={() => setDeviceHover(index)} onBlur={() => setDeviceHover(null)} aria-label={`${device.label}: ${device.value} visits`} style={{ opacity: deviceHover === null || deviceHover === index ? 1 : .3 }}><i style={{ background: palette[index % palette.length] }} /><span>{device.label}</span><strong>{device.value.toLocaleString('en-US')}</strong></Button>)}</div>
    </Card>
    <Card className="glass analytics-chart analytics-time-card"><ChartHeading title="Visits over time" target="Visits" onDetails={onDetails} />
      <div className="analytics-time-body"><div className="analytics-time-plot interactive-chart"><svg viewBox="0 0 400 100" preserveAspectRatio="none" tabIndex={0} role="img" aria-label="Visits throughout the day. Hover or use arrow keys to inspect." onPointerMove={event => { const bounds = event.currentTarget.getBoundingClientRect(); setTimeHover(Math.min(8, Math.max(0, Math.round((event.clientX - bounds.left) / bounds.width * 8)))) }} onPointerLeave={() => setTimeHover(null)} onFocus={() => setTimeHover(4)} onBlur={() => setTimeHover(null)} onKeyDown={event => { if (event.key === 'Escape') setTimeHover(null); if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') { event.preventDefault(); setTimeHover(index => Math.min(8, Math.max(0, (index ?? 4) + (event.key === 'ArrowLeft' ? -1 : 1)))) } }}>
        <defs><linearGradient id={fillId} x1="0" y1="0" x2="0" y2="1"><stop stopColor="#4eb43c" stopOpacity=".65" /><stop offset="100%" stopColor="#4eb43c" stopOpacity="0" /></linearGradient></defs><ChartGrid /><path d={`M${timePoints.replace(/ /g, ' L')} L400,100 L0,100 Z`} fill={`url(#${fillId})`} />{timePoint && <><line className="chart-hover-guide" x1={timePoint.x} x2={timePoint.x} y1="0" y2="100" vectorEffect="non-scaling-stroke" /><circle cx={timePoint.x} cy={timePoint.y} r="2" fill="#4eb43c" /></>}
      </svg>{timePoint && timeHover !== null && <div className="chart-hover-tooltip" role="status" style={{ left: `${Math.min(78, Math.max(22, timePoint.x / 4))}%` }}><span>{chartTimes[timeHover]}</span><strong>{values[timeHover]} visits</strong></div>}</div><div className="analytics-time-labels"><span>00:00</span><span>12:00</span><span>23:59</span></div></div>
    </Card>
    <Card className="glass analytics-chart analytics-bar-card"><ChartHeading title="Funnel retention" target="My Funnel" onDetails={onDetails} />
      <div className="analytics-bars" role="img" aria-label={`Funnel retention: ${data['My Funnel'].rows.map(row => `${row[0]} ${row[1]} users`).join(', ')}`}>{data['My Funnel'].rows.map((row, index) => <div className="analytics-bar-row" key={row[0]} title={`${row[0]}: ${row[1]} users, ${row[2]} of visitors`}><span>{row[0]}</span><div className="analytics-horizontal-track"><span style={{ width: `${Math.min(100, number(row[2]))}%`, background: funnelPalette[index % funnelPalette.length] }} /></div><strong>{row[1]}</strong></div>)}</div>
    </Card>
  </div>
}

/* Light mode: the same translucent white material at every surface level.
   Nested 80% white surfaces naturally composite into brighter white layers. */
.lillian-dashboard[data-theme=light]{
  --surface-fill:rgb(255 255 255 / 80%);
  --surface-stroke:#fff;
  --surface-stroke-width:2px;
  --surface-shadow:0 9px 20px -7px rgb(46 69 55 / 9%),0 16px 40px -8px rgb(46 69 55 / 4%);
  --dashboard-border:var(--surface-stroke);
  --dashboard-divider:rgb(120 145 127 / 14%);
}
.lillian-dashboard[data-theme=light] :is(
  .white-layer,.glass,.inset-surface,.round-button,.source-chip,.profile-trigger,.lily-logo,
  .summary-arrow,.chart-hover-tooltip,.chat-bubble,.chat-composer,.chat-lily,
  .conversation-bubble,.thread-avatar,.page-status,.activity-item-icon,
  .classic-settings-form,.workspace-action
){
  background:var(--surface-fill);
  border:var(--surface-stroke-width) solid var(--surface-stroke);
  box-shadow:var(--surface-shadow);
}
.lillian-dashboard[data-theme=light] :is(
  .search-field input,.workspace-page input,.workspace-page select,
  .profile-tools-panel input,.detail-panel input
){
  background:var(--surface-fill);
  border:var(--surface-stroke-width) solid var(--surface-stroke);
  box-shadow:var(--surface-shadow);
}
.lillian-dashboard[data-theme=light] :is(
  .profile-actions-grid button,.profile-account-list button,
  .navbar-activity-list>button,.classic-tabs button,.page-filter-tabs button,
  .inbox-thread,.classic-tab-panel fieldset
){
  background:var(--surface-fill);
  border:var(--surface-stroke-width) solid var(--surface-stroke);
  box-shadow:var(--surface-shadow);
}
.lillian-dashboard[data-theme=light] .classic-tabs button[aria-selected=true]{
  background:var(--surface-fill);
  border:var(--surface-stroke-width) solid var(--surface-stroke);
  border-bottom-color:transparent;
  box-shadow:var(--surface-shadow);
}
.lillian-dashboard[data-theme=light] .calendar-connected-surface{background:var(--surface-fill)}
.lillian-dashboard[data-theme=light] .calendar-connected-outline{color:var(--surface-stroke)}
.lillian-dashboard[data-theme=light] .calendar-bookmark{filter:drop-shadow(0 9px 15px rgb(46 69 55 / 9%)) drop-shadow(0 16px 32px rgb(46 69 55 / 4%))}
.lillian-dashboard[data-theme=light] .calendar-bookmark .date-preset[aria-pressed=true]{
  background:var(--surface-fill);
  border:var(--surface-stroke-width) solid var(--surface-stroke);
  box-shadow:var(--surface-shadow);
}
.lillian-dashboard[data-theme=light] .dashboard-column>[data-slot=card].glass:hover{box-shadow:0 12px 25px -7px rgb(46 69 55 / 12%),0 16px 40px -8px rgb(46 69 55 / 4%)}
/* Lines separate content; they are not additional surface strokes. */
.lillian-dashboard[data-theme=light] :is(
  .profile-actions-grid,.navbar-activity-content,.calendar-bookmark-footer,
  .date-presets,.ai-chat-header,.conversation-heading,.inbox-composer,
  .inbox-thread-list,.settings-footer,.security-summary
){border-color:var(--dashboard-divider)}
.lillian-dashboard[data-theme=light] .order-table .order-row{border-bottom:1px solid var(--dashboard-divider)}
.lillian-dashboard[data-theme=light] .order-table .order-row:last-child{border-bottom:0}
.lillian-dashboard[data-theme=dark] .calendar-connected-outline path{stroke-width:1px}

/* Text fields use a quiet grey outline instead of the raised surface shadow. */
.lillian-dashboard{--text-input-border:#d4dbd6;--text-input-focus:#91a497}
.lillian-dashboard[data-theme=dark]{--text-input-border:#59685e;--text-input-focus:#9bb4a2}
.lillian-dashboard[data-theme] :is(input[data-slot=input],textarea,.orders-search,.chat-composer){
  border:1px solid var(--text-input-border);
  box-shadow:none;
}
.lillian-dashboard[data-theme] :is(input[data-slot=input],textarea):focus-visible{
  border-color:var(--text-input-focus);
  outline:1px solid var(--text-input-focus);
  outline-offset:1px;
  box-shadow:none;
}
.lillian-dashboard[data-theme] :is(.orders-search,.chat-composer):focus-within{border-color:var(--text-input-focus)}
.lillian-dashboard[data-theme] :is(.orders-search,.chat-composer) input[data-slot=input]{
  border:0;
  background:transparent;
  outline:none;
  box-shadow:none;
}
.lillian-dashboard[data-theme] .navbar-search-mode input[data-slot=input]{height:65%;border-radius:999px;padding:0 .8cqw}

'use client'

import { useState } from 'react'
import { Check, UserRound, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'

export type DemoProfile = { name: string; email: string; account: string }
export const defaultProfile: DemoProfile = { name: 'Alex Morgan', email: 'alex@example.com', account: 'Lillian Studio' }
export function ProfilePanel({ mode, profile, onSave, onClose }: { mode: 'Edit profile' | 'Switch account'; profile: DemoProfile; onSave: (profile: DemoProfile) => void; onClose: () => void }) {
  const [draft, setDraft] = useState(profile)
  return <section className="detail-panel glass profile-tools-panel" aria-label={mode}><div className="panel-heading"><h2>{mode}</h2><Button variant="ghost" size="icon" aria-label="Close profile panel" onClick={onClose}><X /></Button></div>
    {mode === 'Edit profile' ? <form onSubmit={event => { event.preventDefault(); onSave(draft); onClose() }}><label>Name<Input autoFocus required value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} maxLength={80} /></label><label>Email<Input required type="email" value={draft.email} onChange={event => setDraft({ ...draft, email: event.target.value })} /></label><Button type="submit">Save profile</Button></form> : <div className="profile-account-list">{['Lillian Studio', 'Personal workspace'].map(account => <Button variant="ghost" key={account} onClick={() => { onSave({ ...profile, account }); onClose() }}><UserRound /><span>{account}<small>Demo account</small></span>{profile.account === account && <Check />}</Button>)}</div>}
  </section>
}

'use client'

import { useEffect, useRef, useState, type ReactNode } from 'react'
import { ArrowUpRight, Check, Mail, Pause, Play, Plus, Send } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import type { DetailData, DetailView } from './widget-details'
import { AnalyticsCharts } from './analytics-charts'
import './workspace-pages.css'

export const workspaceRoutes = { Campaigns: '#/campaigns', Analytics: '#/analytics', Inbox: '#/inbox', Settings: '#/settings' } as const
export type WorkspacePage = keyof typeof workspaceRoutes
export function workspacePageFromHash(): WorkspacePage | null {
  if (typeof window === 'undefined') return null
  return (Object.keys(workspaceRoutes) as WorkspacePage[]).find(page => workspaceRoutes[page] === window.location.hash) ?? null
}
function useSaved<T>(key: string, initial: T) {
  const [value, setValue] = useState<T>(() => { try { const saved = localStorage.getItem(key); return saved ? { ...initial, ...JSON.parse(saved) } : initial } catch { return initial } })
  useEffect(() => { try { localStorage.setItem(key, JSON.stringify(value)) } catch { /* Local persistence is optional. */ } }, [key, value])
  return [value, setValue] as const
}
function PageFrame({ title, actions, children }: { title: string; actions?: ReactNode; children: ReactNode }) {
  const main = useRef<HTMLElement>(null)
  useEffect(() => { main.current?.focus() }, [title])
  return <main ref={main} className="workspace-page" aria-label={title} tabIndex={-1}>{actions && <div className="workspace-page-actions">{actions}</div>}{children}</main>
}

type Campaign = { id: number; name: string; channel: string; status: 'Active' | 'Paused' | 'Draft'; visits: number; conversions: number }
const initialCampaigns: Campaign[] = [
  { id: 1, name: 'Autumn collection', channel: 'Meta Ads', status: 'Active', visits: 420, conversions: 12 },
  { id: 2, name: 'Welcome to Lillian', channel: 'Email', status: 'Active', visits: 310, conversions: 8 },
  { id: 3, name: 'Back for something new', channel: 'Social', status: 'Paused', visits: 270, conversions: 4 },
  { id: 4, name: 'November launch', channel: 'Email', status: 'Draft', visits: 0, conversions: 0 },
]
function CampaignsPage({ query }: { query: string }) {
  const [saved, setSaved] = useSaved('lillian-campaigns', { campaigns: initialCampaigns })
  const [filter, setFilter] = useState('All')
  const [creating, setCreating] = useState(false)
  const [name, setName] = useState('')
  const [channel, setChannel] = useState('Email')
  const visible = saved.campaigns.filter(item => (filter === 'All' || item.status === filter) && `${item.name} ${item.channel}`.toLowerCase().includes(query.toLowerCase()))
  return <PageFrame title="Campaigns" actions={<Button className="workspace-action" onClick={() => setCreating(!creating)}><Plus />New campaign</Button>}>
    {creating && <form className="glass campaign-create" onSubmit={event => { event.preventDefault(); if (!name.trim()) return; setSaved({ campaigns: [...saved.campaigns, { id: Date.now(), name: name.trim(), channel, status: 'Draft', visits: 0, conversions: 0 }] }); setName(''); setCreating(false); setFilter('All') }}><label>Campaign name<Input autoFocus required value={name} onChange={event => setName(event.target.value)} placeholder="Name your campaign" maxLength={80} /></label><label>Channel<select value={channel} onChange={event => setChannel(event.target.value)}><option>Email</option><option>Meta Ads</option><option>Social</option></select></label><Button className="workspace-action" type="submit">Create draft</Button><Button variant="ghost" type="button" onClick={() => setCreating(false)}>Cancel</Button></form>}
    <Card className="glass workspace-surface"><div className="page-filter-tabs" role="group" aria-label="Campaign status">{['All', 'Active', 'Paused', 'Draft'].map(status => <Button variant="ghost" key={status} aria-pressed={filter === status} onClick={() => setFilter(status)}>{status}</Button>)}</div><div className="page-table-scroll"><table className="page-table"><thead><tr><th>Campaign</th><th>Channel</th><th>Status</th><th>Visits</th><th>Conversions</th><th><span className="visually-hidden">Actions</span></th></tr></thead><tbody>{visible.map(item => <tr key={item.id}><td>{item.name}</td><td>{item.channel}</td><td><span className="page-status">{item.status}</span></td><td>{item.visits}</td><td>{item.conversions}</td><td><Button variant="ghost" size="icon" aria-label={`${item.status === 'Active' ? 'Pause' : 'Start'} ${item.name}`} onClick={() => setSaved({ campaigns: saved.campaigns.map(campaign => campaign.id === item.id ? { ...campaign, status: campaign.status === 'Active' ? 'Paused' : 'Active' } : campaign) })}>{item.status === 'Active' ? <Pause /> : <Play />}</Button></td></tr>)}</tbody></table>{!visible.length && <p className="workspace-empty">No campaigns match this view.</p>}</div></Card>
  </PageFrame>
}
function AnalyticsPage({ data, onDetails }: { data: Record<DetailView, DetailData>; onDetails: (view: DetailView) => void }) {
  const main = useRef<HTMLElement>(null)
  useEffect(() => { main.current?.focus() }, [])
  return <main ref={main} className="workspace-page analytics-page" aria-label="Analytics" tabIndex={-1}>
    <div className="analytics-metrics">{(['Visits', 'Sign-ins', 'My Funnel'] as const).map(view => <Card className="glass analytics-metric" key={view}><span>{view === 'My Funnel' ? 'Conversion' : view}</span><strong>{data[view].value}</strong><Button variant="ghost" className="round-button" aria-label={`View ${view} details`} onClick={() => onDetails(view)}><ArrowUpRight /></Button></Card>)}</div>
    <AnalyticsCharts data={data} onDetails={onDetails} />
  </main>
}

type Thread = { id: number; name: string; subject: string; unread: boolean; messages: { from: 'customer' | 'you'; text: string }[] }
const initialThreads: Thread[] = [
  { id: 1, name: 'Olivia Rhye', subject: 'A question about my subscription', unread: true, messages: [{ from: 'customer', text: 'Hi! Where can I find my next renewal date?' }] },
  { id: 2, name: 'Lana Steiner', subject: 'Thanks for the update', unread: true, messages: [{ from: 'customer', text: 'The new dashboard looks great. Thank you!' }] },
  { id: 3, name: 'Phoenix Baker', subject: 'Annual plan details', unread: false, messages: [{ from: 'customer', text: 'Could you share what is included in the annual plan?' }] },
]
function InboxPage({ query }: { query: string }) {
  const [saved, setSaved] = useSaved('lillian-inbox', { threads: initialThreads })
  const [selected, setSelected] = useState(1)
  const [reply, setReply] = useState('')
  const thread = saved.threads.find(item => item.id === selected)!
  const visible = saved.threads.filter(item => `${item.name} ${item.subject}`.toLowerCase().includes(query.toLowerCase()))
  return <PageFrame title="Inbox"><Card className="glass inbox-workspace"><div className="inbox-thread-list" aria-label="Conversations">{visible.map(item => <button key={item.id} className={`inbox-thread ${selected === item.id ? 'is-selected' : ''}`} aria-pressed={selected === item.id} onClick={() => { setSelected(item.id); setReply(''); setSaved({ threads: saved.threads.map(current => current.id === item.id ? { ...current, unread: false } : current) }) }}><span className="thread-avatar">{item.name.split(' ').map(part => part[0]).join('')}</span><span><strong>{item.name}</strong><small>{item.subject}</small></span>{item.unread && <i aria-label="Unread" />}</button>)}{!visible.length && <p className="workspace-empty">No matching conversations.</p>}</div><section className="inbox-conversation" aria-label={`Conversation with ${thread.name}`}><div className="conversation-heading"><Mail /><div><h2>{thread.name}</h2><p>{thread.subject}</p></div></div><div className="conversation-messages" role="log" aria-live="polite">{thread.messages.map((item, index) => <div className={`conversation-bubble ${item.from === 'you' ? 'from-you' : ''}`} key={index}><span>{item.from === 'you' ? 'You' : thread.name}</span><p>{item.text}</p></div>)}</div><form className="inbox-composer" onSubmit={event => { event.preventDefault(); if (!reply.trim()) return; setSaved({ threads: saved.threads.map(item => item.id === selected ? { ...item, unread: false, messages: [...item.messages, { from: 'you', text: reply.trim() }] } : item) }); setReply('') }}><Input aria-label="Reply to conversation" placeholder="Write a reply…" value={reply} onChange={event => setReply(event.target.value)} maxLength={2000} /><Button type="submit" className="workspace-action" disabled={!reply.trim()}><Send /><span>Send demo reply</span></Button></form></section></Card></PageFrame>
}

const settingsTabs = ['General', 'Team', 'Billing', 'Notifications', 'Integrations', 'Security'] as const
export type SettingsTab = typeof settingsTabs[number]
const defaults = { workspace: 'Lillian Studio', email: 'hello@example.com', timezone: 'Africa/Casablanca', currency: 'USD', plan: 'Pro', cycle: 'Monthly', orderAlerts: true, campaignAlerts: false, weeklyDigest: true, emailIntegration: false, analyticsIntegration: false, session: '7 days' }
function SettingsPage({ initialTab = 'General' }: { initialTab?: SettingsTab }) {
  const [saved, setSaved] = useSaved('lillian-settings', defaults)
  const [draft, setDraft] = useState(saved)
  const [tab, setTab] = useState<SettingsTab>(initialTab)
  const [notice, setNotice] = useState('')
  const [team, setTeam] = useSaved('lillian-team', { members: [{ email: 'owner@example.com', role: 'Owner' }, { email: 'alex@example.com', role: 'Admin' }] })
  const [invite, setInvite] = useState('')
  const tabs = useRef<(HTMLButtonElement | null)[]>([])
  const check = (key: 'orderAlerts' | 'campaignAlerts' | 'weeklyDigest' | 'emailIntegration' | 'analyticsIntegration', label: string) => <label className="settings-checkbox"><input type="checkbox" checked={draft[key]} onChange={event => { setDraft({ ...draft, [key]: event.target.checked }); setNotice('') }} />{label}</label>
  const select = (key: 'timezone' | 'currency' | 'plan' | 'cycle' | 'session', label: string, options: string[]) => <label className="settings-field">{label}<select value={draft[key]} onChange={event => { setDraft({ ...draft, [key]: event.target.value }); setNotice('') }}>{options.map(option => <option key={option}>{option}</option>)}</select></label>
  return <PageFrame title="Settings"><div className="settings-tabs-layout"><div className="classic-tabs" role="tablist" aria-label="Settings sections">{settingsTabs.map((name, index) => <Button ref={element => { tabs.current[index] = element }} variant="ghost" role="tab" id={`settings-tab-${name}`} aria-controls={`settings-panel-${name}`} aria-selected={tab === name} tabIndex={tab === name ? 0 : -1} key={name} onClick={() => { setTab(name); setNotice('') }} onKeyDown={event => {
    const next = event.key === 'ArrowRight' ? (index + 1) % settingsTabs.length : event.key === 'ArrowLeft' ? (index + settingsTabs.length - 1) % settingsTabs.length : event.key === 'Home' ? 0 : event.key === 'End' ? settingsTabs.length - 1 : -1
    if (next >= 0) { event.preventDefault(); setTab(settingsTabs[next]); tabs.current[next]?.focus() }
  }}>{name}</Button>)}</div>
    <form className="classic-settings-form" onSubmit={event => { event.preventDefault(); setSaved(draft); setNotice('Preferences saved.') }}>
      <section role="tabpanel" id={`settings-panel-${tab}`} aria-labelledby={`settings-tab-${tab}`} className="classic-tab-panel" tabIndex={0}>
        {tab === 'General' && <fieldset><legend>Workspace information</legend><div className="settings-fields"><label className="settings-field">Workspace name<Input required value={draft.workspace} onChange={event => { setDraft({ ...draft, workspace: event.target.value }); setNotice('') }} /></label><label className="settings-field">Contact email<Input required type="email" value={draft.email} onChange={event => { setDraft({ ...draft, email: event.target.value }); setNotice('') }} /></label>{select('timezone', 'Time zone', ['Africa/Casablanca', 'UTC', 'Europe/London', 'America/New_York'])}{select('currency', 'Currency', ['USD', 'EUR', 'MAD', 'GBP'])}</div></fieldset>}
        {tab === 'Team' && <fieldset><legend>Workspace members</legend><table className="page-table"><thead><tr><th>Email</th><th>Role</th></tr></thead><tbody>{team.members.map(member => <tr key={member.email}><td>{member.email}</td><td>{member.role}</td></tr>)}</tbody></table><div className="team-invite"><Input type="email" aria-label="New member email" placeholder="teammate@example.com" value={invite} onChange={event => setInvite(event.target.value)} /><Button type="button" variant="outline" onClick={() => { if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(invite.trim())) { setNotice('Enter a valid email address.'); return } if (team.members.some(member => member.email.toLowerCase() === invite.trim().toLowerCase())) { setNotice('This member is already in your workspace.'); return } setTeam({ members: [...team.members, { email: invite.trim(), role: 'Member' }] }); setInvite(''); setNotice('Added to the local team list. No invitation was sent.') }}>Add member</Button></div></fieldset>}
        {tab === 'Billing' && <fieldset><legend>Plan preferences</legend><div className="settings-fields">{select('plan', 'Plan', ['Starter', 'Pro', 'Business'])}{select('cycle', 'Billing cycle', ['Monthly', 'Annual'])}</div><p className="settings-note">Plan previews only. No payment or subscription changes are made.</p></fieldset>}
        {tab === 'Notifications' && <fieldset><legend>Email notifications</legend>{check('orderAlerts', 'New order alerts')}{check('campaignAlerts', 'Campaign activity')}{check('weeklyDigest', 'Weekly performance digest')}</fieldset>}
        {tab === 'Integrations' && <fieldset><legend>Integration preferences</legend>{check('emailIntegration', 'Email platform')}{check('analyticsIntegration', 'Analytics platform')}<p className="settings-note">Demo preferences. No external accounts are connected.</p></fieldset>}
        {tab === 'Security' && <fieldset><legend>Sessions & access</legend>{select('session', 'Preferred session duration', ['1 day', '7 days', '30 days'])}<p className="settings-note">This preference is stored locally. Authentication and access enforcement require a connected backend.</p><div className="security-summary"><span>Workspace role</span><strong>Owner</strong></div></fieldset>}
      </section>
      <div className="settings-footer"><span role="status">{notice}</span><Button variant="outline" type="button" onClick={() => { setDraft(saved); setNotice('Unsaved changes discarded.') }}>Cancel</Button><Button className="workspace-action" type="submit"><Check />Apply</Button></div>
    </form>
  </div></PageFrame>
}

export function WorkspacePages({ page, query, data, onDetails, initialSettingsTab = 'General' }: { page: WorkspacePage; query: string; data: Record<DetailView, DetailData>; onDetails: (view: DetailView) => void; initialSettingsTab?: SettingsTab }) {
  if (page === 'Campaigns') return <CampaignsPage query={query} />
  if (page === 'Analytics') return <AnalyticsPage data={data} onDetails={onDetails} />
  if (page === 'Inbox') return <InboxPage query={query} />
  return <SettingsPage initialTab={initialSettingsTab} />
}

