'use client'

import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { ChartGrid } from './chart-grid'
import { chartCounts, chartTimes, parseChartPoints } from './chart-data'

type Source = { key: string; label: string; color: string; points: string }
export function SourcesChart({ sources, hidden, onToggle }: { sources: Source[]; hidden: string[]; onToggle: (key: string) => void }) {
  const [hover, setHover] = useState<{ key: string; index: number } | null>(null)
  const [badgeHover, setBadgeHover] = useState<string | null>(null)
  const visible = sources.filter(source => !hidden.includes(source.key))
  const activeKey = hover?.key ?? badgeHover
  const active = sources.find(source => source.key === hover?.key)
  const point = active && hover ? parseChartPoints(active.points)[hover.index] : null
  const ordered = [sources[2], sources[1], sources[3], sources[0], sources[4]].filter(source => !hidden.includes(source.key))

  return <>
    <div className="sources-chart interactive-chart">
      <svg viewBox="0 0 750 210" preserveAspectRatio="none" role="img" aria-label="Acquisition sources. Hover for visits, or use left and right arrows for time and up and down for source." tabIndex={0} onPointerMove={event => {
        if (!visible.length) return
        const bounds = event.currentTarget.getBoundingClientRect()
        const x = (event.clientX - bounds.left) / bounds.width * 750
        const y = (event.clientY - bounds.top) / bounds.height * 210
        const index = Math.min(8, Math.max(0, Math.round(x / 750 * 8)))
        const nearest = visible.reduce((best, source) => Math.abs(parseChartPoints(source.points)[index].y - y) < Math.abs(parseChartPoints(best.points)[index].y - y) ? source : best)
        setHover({ key: nearest.key, index }); setBadgeHover(null)
      }} onPointerLeave={() => setHover(null)} onFocus={() => { if (visible[0]) setHover({ key: visible[0].key, index: 4 }) }} onBlur={() => setHover(null)} onKeyDown={event => {
        if (!visible.length || !['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Escape'].includes(event.key)) return
        event.preventDefault()
        if (event.key === 'Escape') { setHover(null); return }
        const sourceIndex = Math.max(0, visible.findIndex(source => source.key === hover?.key))
        const nextSource = event.key === 'ArrowUp' ? (sourceIndex + visible.length - 1) % visible.length : event.key === 'ArrowDown' ? (sourceIndex + 1) % visible.length : sourceIndex
        setHover({ key: visible[nextSource].key, index: Math.min(8, Math.max(0, (hover?.index ?? 4) + (event.key === 'ArrowLeft' ? -1 : event.key === 'ArrowRight' ? 1 : 0))) })
      }}>
        <defs>{sources.map(source => <linearGradient key={source.key} id={`lillian-${source.key}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={source.color} className="source-gradient-stop" stopOpacity={activeKey === source.key ? .6 : .36} /><stop offset="60%" stopColor={source.color} className="source-gradient-stop" stopOpacity={activeKey === source.key ? .25 : .12} /><stop offset="100%" stopColor={source.color} stopOpacity="0" /></linearGradient>)}</defs>
        <ChartGrid />
        {ordered.map(source => <polygon className="source-area" key={source.key} points={`0,210 ${source.points} 750,210`} fill={`url(#lillian-${source.key})`} opacity={activeKey && activeKey !== source.key ? .15 : 1} />)}
        {point && active && <><line className="chart-hover-guide" x1={point.x} x2={point.x} y1="0" y2="210" vectorEffect="non-scaling-stroke" /><ellipse cx={point.x} cy={point.y} rx="4" ry="4" fill={active.color} stroke="white" strokeWidth="1" vectorEffect="non-scaling-stroke" /></>}
      </svg>
      {point && active && hover && <div className="chart-hover-tooltip" role="status" style={{ left: `${Math.min(78, Math.max(22, point.x / 750 * 100))}%` }}><span><i style={{ background: active.color }} />{active.label} · {chartTimes[hover.index]}</span><strong>{chartCounts(active.points, 210, 240)[hover.index]} visits</strong></div>}
    </div>
    <div className="source-legend">{sources.map(source => <Button className={`source-chip ${hidden.includes(source.key) ? 'is-muted' : ''} ${activeKey && activeKey !== source.key ? 'source-chip-dimmed' : ''}`} key={source.key} aria-pressed={!hidden.includes(source.key)} onPointerEnter={() => { if (!hidden.includes(source.key)) { setBadgeHover(source.key); setHover(null) } }} onPointerLeave={() => setBadgeHover(null)} onFocus={() => { if (!hidden.includes(source.key)) setBadgeHover(source.key) }} onBlur={() => setBadgeHover(null)} onClick={() => { onToggle(source.key); setBadgeHover(null); setHover(null) }}><i style={{ background: source.color }} /><span>{source.label} <strong style={{ color: source.color }}>24%</strong></span></Button>)}</div>
  </>
}

export const chartTimes = ['00:00', '03:00', '06:00', '09:00', '12:00', '15:00', '18:00', '21:00', '23:59']
export function parseChartPoints(points: string) {
  return points.split(' ').map(point => { const [x, y] = point.split(',').map(Number); return { x, y } })
}
// Distribute the sample total across points while preserving its exact sum.
export function chartCounts(points: string, height: number, total: number) {
  const weights = parseChartPoints(points).map(point => height - point.y)
  const sum = weights.reduce((result, weight) => result + weight, 0)
  const values = weights.map(weight => weight / sum * total)
  const counts = values.map(Math.floor)
  const remainder = total - counts.reduce((result, count) => result + count, 0)
  values.map((value, index) => ({ index, fraction: value - counts[index] })).sort((a, b) => b.fraction - a.fraction).slice(0, remainder).forEach(({ index }) => counts[index]++)
  return counts
}

'use client'

import { useEffect, useRef } from 'react'
import { ArrowLeft } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'

export const detailRoutes = { Orders: '#/orders', Visits: '#/visits', 'Sign-ins': '#/sign-ins', 'My Funnel': '#/funnel', 'Top sources': '#/sources' } as const
export type DetailView = keyof typeof detailRoutes
export function detailViewFromHash(): DetailView | null {
  if (typeof window === 'undefined') return null
  return (Object.keys(detailRoutes) as DetailView[]).find(view => detailRoutes[view] === window.location.hash) ?? null
}
export type DetailData = { value: string; description: string; columns: string[]; rows: string[][]; note?: string }

export function WidgetDetails({ view, data, query, onBack }: { view: DetailView; data: DetailData; query: string; onBack: () => void }) {
  const main = useRef<HTMLElement>(null)
  useEffect(() => { main.current?.focus() }, [view])
  const rows = data.rows.filter(row => row.join(' ').toLowerCase().includes(query.trim().toLowerCase()))
  return <main ref={main} className="widget-details-page" aria-label={view} tabIndex={-1}>
    <Button className="back-to-overview" variant="ghost" onClick={onBack}><ArrowLeft />Back to overview</Button>
    <Card className="glass widget-details-card">
      <div className="widget-details-heading"><strong>{data.value}</strong></div>
      <p className="widget-details-description">{data.description}</p>
      <div className="widget-details-table-wrap"><table className="widget-details-table"><thead><tr>{data.columns.map(column => <th key={column} scope="col">{column}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={index}>{row.map((cell, cellIndex) => <td key={cellIndex}>{cell}</td>)}</tr>)}</tbody></table>{!rows.length && <p className="details-empty">No results match your search.</p>}</div>
      {data.note && <p className="widget-details-note">{data.note}</p>}
    </Card>
  </main>
}

export function ChartGrid() {
  return <g className="chart-grid" aria-hidden="true">
    {Array.from({ length: 9 }, (_, index) => <line key={index} x1={`${index * 12.5}%`} x2={`${index * 12.5}%`} y1="0" y2="100%" vectorEffect="non-scaling-stroke" />)}
  </g>
}

'use client'

import { useRef, useState } from 'react'
import { ArrowUpRight, ChevronLeft, ChevronRight } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { ChartGrid } from './chart-grid'
import { chartCounts, chartTimes, parseChartPoints } from './chart-data'

const slides = [
  { label: 'Orders', value: '$340.00', detail: '24 new orders', growth: '+3%', points: '0,70 50,64 100,69 150,47 200,53 250,35 300,42 350,19 400,27' },
  { label: 'Visits', value: '1,000', detail: 'Unique visitors today', growth: '+12%', points: '0,72 50,58 100,64 150,39 200,47 250,22 300,30 350,10 400,18' },
  { label: 'Sign-ins', value: '310', detail: 'Users signed in today', growth: '+8%', points: '0,74 50,68 100,57 150,63 200,45 250,49 300,30 350,35 400,15' },
] as const

export function TodaySummary() {
  const [current, setCurrent] = useState(0)
  const [hoverIndex, setHoverIndex] = useState<number | null>(null)
  const touchStart = useRef<{ x: number; y: number } | null>(null)
  const move = (direction: number) => { setHoverIndex(null); setCurrent(value => (value + direction + slides.length) % slides.length) }
  const hoverPoint = hoverIndex === null ? null : parseChartPoints(slides[current].points)[hoverIndex]
  const hoverValue = hoverIndex === null ? 0 : chartCounts(slides[current].points, 100, current === 0 ? 34000 : current === 1 ? 1000 : 310)[hoverIndex]

  return <Card className="glass orders-today today-summary">
    <div className="card-heading summary-heading"><h1>Today’s summary</h1></div>
    <section className="summary-carousel" aria-label="Today’s business summary" aria-roledescription="carousel" tabIndex={0} onKeyDown={event => {
      if (event.target !== event.currentTarget) return
      if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') { event.preventDefault(); move(event.key === 'ArrowLeft' ? -1 : 1) }
    }} onTouchStart={event => { touchStart.current = { x: event.touches[0].clientX, y: event.touches[0].clientY } }} onTouchEnd={event => {
      if (!touchStart.current) return
      const dx = event.changedTouches[0].clientX - touchStart.current.x
      const dy = event.changedTouches[0].clientY - touchStart.current.y
      if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy)) move(dx < 0 ? 1 : -1)
      touchStart.current = null
    }}>
      <div className="summary-slide-window">
        {slides.map((slide, index) => {
          const offset = (index - current + slides.length + 1) % slides.length - 1
          return <div className={`summary-slide ${index === current ? 'summary-slide-active' : ''}`} key={slide.label} style={{ transform: `translateX(${offset * 60}%) scale(${offset === 0 ? 1 : 0.78})` }} role="group" aria-roledescription="slide" aria-label={`${index + 1} of ${slides.length}: ${slide.label}`} aria-hidden={index !== current}>
            <span className="summary-metric-label">{slide.label}</span>
            <p className="revenue-number">{slide.value}</p>
            <p className="summary-description">{slide.detail}<span><ArrowUpRight />{slide.growth}</span></p>
          </div>
        })}
      </div>
      <span className="summary-edge summary-edge-left" aria-hidden="true" /><span className="summary-edge summary-edge-right" aria-hidden="true" />
      <Button variant="ghost" className="summary-arrow summary-arrow-left" aria-label={`Previous summary: ${slides[(current + 2) % slides.length].label}`} onClick={() => move(-1)}><ChevronLeft /></Button>
      <Button variant="ghost" className="summary-arrow summary-arrow-right" aria-label={`Next summary: ${slides[(current + 1) % slides.length].label}`} onClick={() => move(1)}><ChevronRight /></Button>
    </section>
    <div className="summary-dots" role="group" aria-label="Select summary metric">{slides.map((slide, index) => <Button variant="ghost" key={slide.label} className="summary-dot-button" aria-label={`Show ${slide.label}`} aria-pressed={current === index} onClick={() => { setCurrent(index); setHoverIndex(null) }}><span /></Button>)}</div>
    <div className="summary-sparkline interactive-chart">
      <svg viewBox="0 0 400 100" preserveAspectRatio="none" role="img" tabIndex={0} aria-label={`${slides[current].label} trend for today. Hover or use left and right arrow keys for details.`} onPointerMove={event => {
        const bounds = event.currentTarget.getBoundingClientRect()
        setHoverIndex(Math.min(8, Math.max(0, Math.round((event.clientX - bounds.left) / bounds.width * 8))))
      }} onPointerLeave={() => setHoverIndex(null)} onFocus={() => setHoverIndex(4)} onBlur={() => setHoverIndex(null)} onKeyDown={event => {
        if (event.key === 'Escape') setHoverIndex(null)
        if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') { event.preventDefault(); setHoverIndex(index => Math.min(8, Math.max(0, (index ?? 4) + (event.key === 'ArrowLeft' ? -1 : 1)))) }
      }}><defs><linearGradient id="summary-trend-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#4eb43c" stopOpacity="1" /><stop offset="100%" stopColor="#4eb43c" stopOpacity="0" /></linearGradient></defs><ChartGrid /><path d={`M${slides[current].points.replace(/ /g, ' L')} L400,100 L0,100 Z`} fill="url(#summary-trend-fill)" />{hoverPoint && <><line className="chart-hover-guide" x1={hoverPoint.x} x2={hoverPoint.x} y1="0" y2="100" vectorEffect="non-scaling-stroke" /><circle cx={hoverPoint.x} cy={hoverPoint.y} r="2" fill="#629d56" stroke="white" strokeWidth="1" vectorEffect="non-scaling-stroke" /></>}</svg>
      {hoverPoint && hoverIndex !== null && <div className="chart-hover-tooltip" role="status" style={{ left: `${Math.min(78, Math.max(22, hoverPoint.x / 400 * 100))}%` }}><span>{slides[current].label} · {chartTimes[hoverIndex]}</span><strong>{current === 0 ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(hoverValue / 100) : `${hoverValue} ${current === 1 ? 'visits' : 'sign-ins'}`}</strong></div>}
    </div>
    <p className="summary-live-status" role="status" aria-live="polite">{slides[current].label}: {slides[current].value}. {slides[current].detail}.</p>
  </Card>
}

'use client'

import { useEffect, useId, useRef, useState } from 'react'
import { DayPicker, type DateRange } from 'react-day-picker'
import { CalendarCheck, Check, ChevronDown } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { customPeriod, formatPeriod, periodPresets, presetPeriod, reportingToday, type ReportingPeriod } from './reporting-period'
import './date-range-drawer.css'

type Props = { value: ReportingPeriod; onChange: (value: ReportingPeriod) => void; theme: 'light' | 'dark' }

export function DateRangeDrawer({ value, onChange, theme }: Props) {
  const [open, setOpen] = useState(false)
  const [draft, setDraft] = useState<DateRange | undefined>({ from: value.from, to: value.to })
  const [draftLabel, setDraftLabel] = useState(value.label)
  const [month, setMonth] = useState(() => new Date(value.from.getFullYear(), value.from.getMonth() - 1, 1))
  const bookmark = useRef<HTMLDivElement>(null)
  const trigger = useRef<HTMLButtonElement>(null)
  const [geometry, setGeometry] = useState({ width: 0, height: 0, tabWidth: 0, neck: 0 })
  const expansion = useRef<HTMLDivElement>(null)
  const regionId = useId()
  useEffect(() => {
    const element = bookmark.current
    if (!element) return
    const measure = () => {
      const width = element.offsetWidth
      const height = element.offsetHeight
      const tabWidth = trigger.current?.offsetWidth ?? width
      const neck = expansion.current?.offsetTop ?? 0
      setGeometry(previous => previous.width === width && previous.height === height && previous.tabWidth === tabWidth && previous.neck === neck ? previous : { width, height, tabWidth, neck })
    }
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    if (trigger.current) observer.observe(trigger.current)
    return () => observer.disconnect()
  }, [])
  const showMonth = (date: Date) => setMonth(new Date(date.getFullYear(), date.getMonth() - 1, 1))
  const { width: w, height: h, tabWidth, neck } = geometry
  const headerHeight = trigger.current?.offsetHeight ?? 0
  const shoulder = Math.max(1, w - tabWidth)
  const left = open ? 1 : shoulder
  const bottom = open ? h : headerHeight
  const join = open ? neck : 1
  const radius = open ? Math.max(0, Math.min(24, Math.max(0, neck - headerHeight), (h - neck) / 2, shoulder / 2)) : 0
  const bottomRadius = Math.max(0, Math.min(24, open ? (h - neck) / 2 : headerHeight / 2))
  // Identical path commands let the browser interpolate the surface without layout work.
  const outline = `M ${shoulder} 1 H ${w - 1} V ${bottom - bottomRadius} Q ${w - 1} ${bottom - 1} ${w - bottomRadius} ${bottom - 1} H ${left + bottomRadius} Q ${left} ${bottom - 1} ${left} ${bottom - bottomRadius} V ${join + radius} Q ${left} ${join} ${left + radius} ${join} H ${shoulder - radius} Q ${shoulder} ${join} ${shoulder} ${join - radius} Z`
  const today = reportingToday()
  const complete = !!draft?.from && !!draft.to
  const close = () => { setOpen(false); trigger.current?.focus() }
  useEffect(() => {
    if (!open) return
    const outside = (event: PointerEvent) => { if (!bookmark.current?.contains(event.target as Node)) setOpen(false) }
    const escape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') { event.stopPropagation(); setOpen(false); trigger.current?.focus() }
    }
    document.addEventListener('pointerdown', outside)
    bookmark.current?.addEventListener('keydown', escape)
    const element = bookmark.current
    return () => { document.removeEventListener('pointerdown', outside); element?.removeEventListener('keydown', escape) }
  }, [open])
  const apply = () => {
    if (!draft?.from || !draft.to) return
    const selected = periodPresets.find(preset => preset === draftLabel)
    onChange(selected ? presetPeriod(selected) : customPeriod(draft.from, draft.to))
    close()
  }

  return <div ref={bookmark} className={`calendar-bookmark calendar-bookmark-layout ${open ? 'calendar-bookmark-open' : ''}`} data-theme={theme}>
    {w > 0 && h > 0 && <><div className="calendar-connected-surface" style={{ clipPath: `path('${outline}')` }} aria-hidden="true" />
    <svg className="calendar-connected-outline" viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" aria-hidden="true"><path d={outline} style={{ d: `path("${outline}")` }} fill="none" stroke="currentColor" strokeWidth="2" vectorEffect="non-scaling-stroke" /></svg></>}
    <Button ref={trigger} variant="ghost" className="date-selector" aria-expanded={open} aria-controls={regionId} aria-label={`Reporting period: ${value.label}, ${formatPeriod(value, true)}`} onClick={() => {
      if (!open) { setDraft({ from: value.from, to: value.to }); setDraftLabel(value.label); setMonth(new Date(value.from.getFullYear(), value.from.getMonth() - 1, 1)) }
      setOpen(!open)
    }}><CalendarCheck /><span className="date-trigger-copy"><strong>{value.label}</strong><span>{formatPeriod(value)}</span></span><ChevronDown className="calendar-bookmark-chevron" /></Button>
    <div ref={expansion} className="calendar-expansion" inert={!open} aria-hidden={!open}>
      <section id={regionId} className="calendar-expansion-inner" aria-label="Select reporting period">
        <div className="calendar-bookmark-scroll">
          <div className="date-presets" role="group" aria-label="Preset periods">{periodPresets.map(preset => <Button variant="ghost" className="date-preset" key={preset} aria-pressed={draftLabel === preset} onClick={() => {
            const next = presetPeriod(preset)
            setDraftLabel(preset); setDraft({ from: next.from, to: next.to }); showMonth(next.from)
          }}><span>{preset}</span>{draftLabel === preset && <Check />}</Button>)}</div>
          <div className="custom-calendar"><div className="calendar-section-heading"><h3>Custom period</h3><Button variant="ghost" onClick={() => { setDraft(undefined); setDraftLabel('Custom range') }}>Clear</Button></div>
            <DayPicker mode="range" selected={draft} onSelect={next => { setDraft(next); setDraftLabel('Custom range') }} month={month} onMonthChange={setMonth} numberOfMonths={2} weekStartsOn={1} showOutsideDays fixedWeeks today={today} disabled={{ after: today }} endMonth={today} captionLayout="dropdown" startMonth={new Date(2000, 0, 1)} navLayout="around" />
            <p className="date-selection-hint" aria-live="polite">{draft?.from ? draft.to ? formatPeriod({ label: draftLabel, from: draft.from, to: draft.to }, true) : `${formatPeriod({ label: draftLabel, from: draft.from, to: draft.from }, true)} — Select an end date` : 'Select a start date, then an end date.'}</p>
          </div>
        </div>
        <div className="calendar-bookmark-footer"><Button variant="ghost" onClick={close}>Cancel</Button><Button className="apply-period" disabled={!complete} onClick={apply}>Apply period</Button></div>
      </section>
    </div>
  </div>
}

